test('a git that cannot say whether HEAD or the default branch has the marker refuses edits, commits and PRs, naming the bypass', () => {
  const { dir } = repo()
  rmSync(join(dir, '.claude/trace.json'))
  const realGit = execFileSync('sh', ['-c', 'command -v git'], { encoding: 'utf8' }).trim()
  // Without the developer's own config, whose safe.directory could let the repository through.
  const refused = `GIT_TEST_ASSUME_DIFFERENT_OWNER=1 GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1 exec "${realGit}" "$@"`
  for (const [why, when, does] of [
    ['times out', 'ls-tree', 'exec sleep 10'],
    ['refuses the repository', 'ls-tree', refused],
    ['is killed by a signal', 'ls-tree', 'kill -9 $$'],
    ['refuses the repository asking whether HEAD is there', 'HEAD^{tree}', refused],
    ['refuses the repository asking for the default branch', 'refs/remotes/origin/HEAD', refused],
  ]) {
    const bin = mkdtempSync(join(tmpdir(), 'git-'))
    try {
      writeFileSync(join(bin, 'git'), `#!/bin/sh\ncase " $* " in *" ${when} "*) ${does};; esac\nexec "${realGit}" "$@"\n`, { mode: 0o755 })
      for (const [tool, input] of /** @type {[string, Record<string, string>][]} */ ([
        ['Edit', { file_path: join(dir, 'a.md') }],
        ['Bash', { command: 'git commit -m "x #6"' }],
        ['Bash', { command: 'gh pr create -t t -b "Closes #6"' }],
      ])) {
        const out = hook({ tool_name: tool, tool_input: input, cwd: dir }, { PATH: `${bin}:${process.env.PATH}` })
        assert.equal(out?.permissionDecision, 'deny', `git ${why}: ${tool} ${JSON.stringify(input)}`)
        assert.match(out.permissionDecisionReason, /could not be checked.*TRACE_BYPASS=1/)
      }
    } finally {
      rmSync(bin, { recursive: true, force: true })
    }
  }
})

