  rmSync(join(dir, '.claude/trace.json'))
  dropObject(dir, 'HEAD:.claude')
  assert.throws(() => worldFor(NO_READS).git.traced(dir), /git ls-tree did not answer/)
  // On a branch that dropped the marker, the default branch is asked.
  for (const [what, ref] of [['a missing commit', '1'.repeat(40)], ['a broken ref', 'garbage']]) {
    const { dir } = dropMarker(repo())
    writeFileSync(join(dir, '.git/refs/heads/main'), `${ref}\\n`)
    assert.throws(() => worldFor(NO_READS).git.traced(dir), /did not answer/, what)
  }
})

const NO_READS = { records: () => null, add() {}, clear() {} }

/** Deletes the object `rev` names from `dir`'s object store. @param {string} dir @param {string} rev */
function dropObject(dir, rev) {
  const oid = execFileSync('git', ['rev-parse', rev], { cwd: dir, encoding: 'utf8' }).trim()
  rmSync(join(dir, '.git/objects', oid.slice(0, 2), oid.slice(2)))
}

